var i=[{title:`Πώς λειτουργούν τα διαλείμματα έντασης`,text:`Ένα διάστημα εργασίας αυξάνει την αναπνοή και τον φόρτο σας, και το διάστημα ανάκτησης σας αφήνει να αναρρώσετε εν μέρει ή κατά το μεγαλύτερο μέρος. Μπορείτε να ρυθμίσετε και τα δύο. Τα διαλείμματα μπορούν να είναι αερόβια, όπως το γρήγορο περπάτημα που εναλλάσσεται με ήπιο περπάτημα, ή πιο έντονα, όπως μια γρήγορη προσπάθεια ποδηλασίας που ακολουθείται από ήπιο πετάλισμα.`},{title:`Ξεκινήστε κάτω από τη μέγιστη προσπάθεια`,text:`Αν είστε νέος στην άσκηση, μπορείτε να εναλλάσσετε ένα λεπτό γρήγορου περπατήματος με δύο λεπτά άνετου περπατήματος για έξι γύρους. Ένας έμπειρος δρομέας μπορεί να χρησιμοποιεί ταχύτερες προσπάθειες με μεγαλύτερη ανάπαυση. Η σωστή ταχύτητα εργασίας εξαρτάται από το επίπεδο και την άσκησή σας, οπότε μια αναλογία χρόνου από μόνη της δεν σας λέει πόσο δύσκολη είναι η εργασία για το σώμα σας.`},{title:`Η διάρκεια ανάκτησης εξαρτάται από τον στόχο`,text:`Οι μεγαλύτερες ανακτήσεις κρατούν υψηλή την ταχύτητα και την ποιότητα κίνησής σας στις έντονες επαναλήψεις. Οι συντομότερες ανακτήσεις κάνουν τη συνεδρία πιο συνεχή και μπορεί να αυξήσουν τη συνολική απαίτηση για την καρδιά και τους πνεύμονές σας, αλλά αν είναι πολύ σύντομες, η ποιότητα πέφτει γρήγορα. Ρυθμίστε την εργασία και την ανάπαυση ώστε να ταιριάζουν στον στόχο φυσικής κατάστασης που έχετε στον νου σας.`},{title:`Ελέγξτε το συνολικό φορτίο`,text:`Προθερμαίνεστε πάντα σταδιακά και τελειώνετε με κάτι ευκολότερο. Χτίστε το συνολικό ποσό εργασίας διαλειμμάτων πριν κάνετε τα διαλείμματα πολύ πιο δύσκολα. Αν η μορφή του περπατήματός σας, η μηχανική του τρεξίματος ή ο συντονισμός σας στο σχοινάκι αρχίζει να χαλά, πάρτε μεγαλύτερη ανάκτηση, μειώστε την ένταση ή τελειώστε τη συνεδρία.`},{title:`Χρήση του TrainUp`,text:`Το χρονόμετρο ανάπαυσης και το χρονόμετρο κράτησης κρατούν τα διαλείμματά σας στην ώρα τους, και μετά την προπόνηση βαθμολογείτε την προσπάθεια της συνεδρίας από το 1 έως το 10. Το πιο δύσκολο δεν είναι αυτόματα καλύτερο. Όταν δημιουργείτε ξανά το πρόγραμμά σας, γίνεται ευκολότερο αν 2 από τις τελευταίες σας 3 προπονήσεις ήταν πολύ δύσκολες (RPE 9 ή περισσότερο) ή ολοκληρώθηκαν λιγότερο από 60%, και ένα βήμα πιο δύσκολο μόνο αν οι τελευταίες 4 ήταν εύκολες και πλήρεις. Αν χρειάζεστε λιγότερη κρούση, η ποδηλασία ή ο γρήγορος βηματισμός δουλεύουν επίσης ως διαλείμματα.`}];var l=[{label:`ACE: σχεδιασμός διαλειμμάτων υψηλής έντασης`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`CDC: μέτρηση της έντασης δραστηριότητας και τεστ ομιλίας`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`Συστάσεις του CDC για τη σωματική δραστηριότητα ενηλίκων`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var s={sections:i,sources:l};export{s as default,i as sections,l as sources};